<script setup lang="ts">
import {ref,computed,onMounted} from 'vue';
import Button from 'primevue/button';import Tag from 'primevue/tag';import Card from 'primevue/card';import Select from 'primevue/select';import DataTable from 'primevue/datatable';import Column from 'primevue/column';import Dialog from 'primevue/dialog';import Message from 'primevue/message';import InputText from 'primevue/inputtext';
import ResearchChart from '../components/ResearchChart.vue';import {api} from '../services/api';
const listing=ref<any>({pairs:[]}),detail=ref<any>(null),pair=ref(''),account=ref('S1_PARTIAL'),error=ref(''),symbol=ref('FPT'),inspect=ref<any>(null),visible=ref(false),busy=ref(false);
const current=computed(()=>detail.value?.accounts.find((x:any)=>x.code===account.value));const plan=computed(()=>detail.value?.plans.find((x:any)=>x.code===account.value));
const positions=computed(()=>Object.entries(current.value?.state_json.positions??{}).map(([symbol,p]:any)=>({symbol,...p,pnl:Number(p.qty)*Number(p.last)-Number(p.cost),return:Number(p.qty)*Number(p.last)/Number(p.cost)-1})));
const orders=computed(()=>[...(plan.value?.exits??[]),...(plan.value?.buys??[])]);
const chartAccount=computed(()=>inspect.value?.accounts.find((a:any)=>a.code===account.value));
const levels=computed(()=>{const p=chartAccount.value?.position,s=chartAccount.value?.signal;return [{price:Number(p?.entry??s?.features_used.raw_close),title:'Giá vào / tham chiếu',color:'#38bdf8'},{price:Number(p?.stop??s?.invalidation_price),title:'Stop',color:'#ef4444'},{price:Number(p?.target),title:'Chốt 1R',color:'#14b8a6'}].filter(x=>Number.isFinite(x.price)&&x.price>0).map(x=>({...x,price:x.price*Number(inspect.value?.bars.at(-1)?.factor??1)}));});
const money=(v:any)=>Number(v??0).toLocaleString('vi-VN',{maximumFractionDigits:0});const pct=(v:any)=>v==null?'—':`${(Number(v)*100).toFixed(2)}%`;
async function load(){busy.value=true;error.value='';try{listing.value=(await api<any>('paper')).data;if(!pair.value)pair.value=listing.value.pairs.find((p:any)=>p.mode==='FORWARD')?.id??'';if(pair.value)detail.value=(await api<any>(`paper/desk/${pair.value}`)).data;}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function open(code:string){error.value='';try{inspect.value=(await api<any>(`paper/desk/${pair.value}/symbol/${code.toUpperCase().trim()}`)).data;visible.value=true;}catch(e){error.value=(e as Error).message;}}
onMounted(load);
</script>
<template>
<div class="page-heading"><div><div class="eyebrow">DAILY QUANT DESK</div><h1>Danh mục & kế hoạch</h1><p>Dữ liệu thật · Tiền giả lập · S1 song song</p></div><Button label="Làm mới" icon="pi pi-refresh" :loading="busy" @click="load"/></div>
<Message v-if="error" severity="error">{{error}}</Message>
<div class="filter-toolbar"><Tag value="PAPER ONLY"/><Tag :value="`EOD ${listing.snapshot?.as_of??'—'}`" severity="secondary"/><Select v-model="pair" :options="listing.pairs.map((p:any)=>({...p,label:`${p.mode} · ${p.cursor_day} · ${p.id.slice(0,8)}`}))" optionLabel="label" optionValue="id" aria-label="Cặp danh mục" @change="load"/><router-link to="/portfolio/ledger">Ledger & phê duyệt</router-link></div>
<Message v-if="!detail&&!busy" severity="info">Chưa có cặp forward. Tạo cặp tại Ledger & phê duyệt.</Message>
<template v-if="detail">
<Message v-if="detail.pair.mode==='REPLAY'" severity="warn">REPLAY lịch sử · Không phải kết quả forward hôm nay.</Message>
<Message v-if="listing.snapshot?.as_of>detail.pair.cursor_day" severity="warn">Danh mục chưa xử lý hết EOD mới. Phê duyệt chạy tiếp tại Ledger để cập nhật kế hoạch.</Message>
<div class="desk-cards"><Card v-for="a in detail.accounts" :key="a.code"><template #title>{{a.code==='S1'?'S1 gốc':'1R · Trail 2 ATR · 15 phiên'}}</template><template #content><div class="nav">{{money(a.equity.at(-1)?.nav??50000000)}} <small>VND</small></div><div class="metrics"><span>Lợi nhuận<strong>{{pct(a.summary_json.return??0)}}</strong></span><span>Drawdown<strong>{{pct(a.summary_json.drawdown??0)}}</strong></span><span>Winrate<strong>{{pct(a.summary_json.winRate)}} <small>({{a.summary_json.closed??0}} lệnh)</small></strong></span></div></template></Card></div>
<div class="filter-toolbar"><Select v-model="account" :options="[{label:'S1 gốc',value:'S1'},{label:'Partial + trailing',value:'S1_PARTIAL'}]" optionLabel="label" optionValue="value" aria-label="Chiến lược"/><Tag :value="plan?.regime" severity="secondary"/><span>Tiền khả dụng <b>{{money(current?.state_json.cash)}}</b></span></div>
<h2>Đang nắm giữ <small>{{positions.length}} mã</small></h2>
<DataTable :value="positions" size="small" scrollable><template #empty>Đang giữ tiền mặt.</template><Column header="Mã"><template #body="{data}"><Button :label="data.symbol" link @click="open(data.symbol)"/></template></Column><Column field="qty" header="SL"/><Column header="Giá vốn"><template #body="{data}">{{money(data.entry)}}</template></Column><Column header="Giá EOD"><template #body="{data}">{{money(data.last)}}</template></Column><Column header="Lãi/lỗ chưa thực hiện"><template #body="{data}">{{money(data.pnl)}} · {{pct(data.return)}}</template></Column><Column header="Stop"><template #body="{data}">{{money(data.stop)}}</template></Column><Column header="1R"><template #body="{data}">{{data.target?money(data.target):'—'}}</template></Column></DataTable>
<h2>Kế hoạch phiên kế tiếp</h2><p class="muted">Tín hiệu {{plan?.decisionDay}} → {{plan?.nextSession??'Chờ xác nhận lịch phiên mới'}} · Khớp giả lập khi có EOD.</p>
<DataTable :value="orders" size="small" scrollable><template #empty>Không có lệnh mới. {{plan?.regime==='RISK_OFF'?'Thị trường RISK_OFF: S1 giữ tiền mặt.':'Chưa có tín hiệu đạt điều kiện.'}}</template><Column header="Mã"><template #body="{data}"><Button :label="data.symbol" link @click="open(data.symbol)"/></template></Column><Column field="side" header="Chiều"/><Column field="type" header="Loại giả lập"/><Column field="quantity" header="SL dự kiến"/><Column header="Tham chiếu"><template #body="{data}">{{money(data.reference)}}</template></Column><Column header="Stop"><template #body="{data}">{{money(data.stop)}}</template></Column><Column field="status" header="Trạng thái"/></DataTable>
<p class="muted">Mua theo giá mở cửa giả lập, không phải lệnh market gửi sàn. SL ước tính theo giá EOD; giá mở cửa, hạn mức và thanh khoản sẽ quyết định khớp.</p>
<div class="filter-toolbar"><InputText v-model="symbol" aria-label="Mã cần xem" placeholder="FPT" @keyup.enter="open(symbol)"/><Button label="Chart & checklist" icon="pi pi-chart-line" @click="open(symbol)"/></div>
</template>
<Dialog v-model:visible="visible" modal :header="`${inspect?.symbol??''} · ${inspect?.day??''}`" :style="{width:'min(1150px,96vw)'}"><div v-if="inspect" class="symbol-layout"><div class="chart"><ResearchChart v-if="inspect.bars.length" :bars="inspect.bars" :adjusted="true" :recentBars="180" sourceLabel="VNDIRECT · Giá điều chỉnh" :levels="levels"/><Message v-else severity="warn">Không có giá trong snapshot này.</Message></div><div><h3>Điều kiện mua S1</h3><div v-for="c in chartAccount?.checks??[]" :key="c.label" class="check"><i :class="c.pass===true?'pi pi-check-circle pass':c.pass===false?'pi pi-times-circle fail':'pi pi-minus-circle'"/><span>{{c.label}}<small>{{typeof c.value==='number'?money(c.value):c.value}}</small></span></div><p class="muted">Checklist tại ngày EOD. Dấu ✓ không đảm bảo lệnh được khớp.</p></div></div></Dialog>
</template>
<style scoped>.filter-toolbar :deep(.p-select){max-width:100%}.desk-cards{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1rem}.nav{font-size:2rem;font-weight:700}.nav small,h2 small{font-size:.8rem;color:var(--muted)}.metrics{display:flex;gap:2rem;margin-top:1rem}.metrics span{font-size:.75rem;color:var(--muted)}.metrics strong{display:block;color:var(--text);margin-top:.4rem}.symbol-layout{display:grid;grid-template-columns:minmax(0,2fr) minmax(0,1fr);gap:1.5rem}.chart{min-width:0}.check{display:flex;gap:.7rem;padding:.6rem 0;border-bottom:1px solid var(--line)}.check small{display:block;color:var(--muted);margin-top:.2rem}.pass{color:#14b8a6}.fail{color:#f97316}h2{font-size:1.15rem;margin-top:2rem}@media(max-width:800px){.desk-cards,.symbol-layout{grid-template-columns:minmax(0,1fr)}.metrics{gap:1rem}}</style>
